function dReifT() {
  return CW('dt-reified-generics', {
    code: ['Object o = <int>[1, 2];', 'o is List<int>     // true', 'o is List<String>  // false', 'T firstOf<T>(List<T> l)  // T = int', '// type arguments kept at runtime'],
    hl: [[0, 3, 'ok'], [3, 1, 'accent'], [4, 1, 'accent'], null],
    draw: (S) => {
      mono(S, 'm0', 19.0, .5, nbs(['is List<int>      true', 'is List<num>      true', 'is List<String>   false', 'is List<Object?>  true', 'runtimeType       List<int>']), 1, { w: 12.4, dy: .55, c: 'dtx-w' });
      lbl(S, 'l1', 19.0, 3.4, ['실행 중에도 리스트는 자신이 List<int>라는 것을 알고 있었어요', 'at runtime the list still knew it was a List<int>'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.8, ['제네릭 함수 안에서 T를 출력하자 int, num, String이 나왔어요', 'printing T inside a generic function gave int, num and String'], 'a', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.2, ['Java처럼 지워지지 않고 남아요', 'they are not erased as in Java'], 'w', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['is List<int> 같은 검사를 실행 중에 믿고 써도 돼요', 'runtime checks such as is List<int> can be trusted'], 'a', 4, { w: 16.0 });
    },
    notes: [['<int>[1, 2]로 만든 리스트를 Object 변수에 담고, 여러 타입으로 is 검사를 했어요 · 변수의 정적 타입은 Object라서 컴파일러는 원소 타입을 모르는 상태예요', 'a list made as <int>[1, 2] was stored in an Object variable and checked with is against several types, the variable\'s static type being Object so the compiler did not know the element type'], ['is List<int>와 is List<num>, is List<Object?>는 true, is List<String>은 false였어요 · runtimeType은 List<int>였어요 · 리스트 객체가 자기 타입 인자를 들고 있어요', 'is List<int>, is List<num> and is List<Object?> were true and is List<String> false, with runtimeType List<int>, since the list object carries its own type argument'], ['T firstOf<T>(List<T> l) 안에서 T를 출력하자 [1, 2]에는 int, <num>[1, 2]에는 num, [\'a\']에는 String이 나왔어요 · 함수의 타입 인자도 실행 중에 값으로 남아요', 'printing T inside T firstOf<T>(List<T> l) gave int for [1, 2], num for <num>[1, 2] and String for [\'a\'], so a function\'s type arguments also remain as values at runtime'], ['Java는 컴파일 뒤 제네릭 타입 인자를 지워서 List<String>과 List<Integer>를 실행 중에 구별하지 못해요 · Dart는 타입 인자를 남겨 두는 reified 제네릭이에요 · 다음 항목의 공변 리스트 검사도 이 덕분에 가능해요', 'Java erases generic type arguments after compilation and cannot tell List<String> from List<Integer> at runtime, whereas Dart keeps them as reified generics, which also makes the covariant list check in the next item possible']],
    fin: [['타입 인자가 남아요', 'type arguments remain', 'dtx-xs dtx-a'], ['is 검사가 정확해요', 'is checks are exact'], ['T도 값이에요', 'T is a value too']],
    caps: [['Object 안의 리스트', 'A list inside Object'], ['is 검사', 'is checks'], ['함수의 T', 'A function\'s T'], ['지우지 않는 제네릭', 'Generics not erased'], ['reified 제네릭', 'Reified generics']]
  });
}

